-- What the migrations install, for review: they run the same DDL, rendered from PERSISTENT. A change here
-- without a migration is a bug. A rename needs a migration that drops the old name.
CREATE TRIGGER projects_updated_at AFTER UPDATE ON projects
WHEN NEW.updated_at IS OLD.updated_at AND NEW.updated_by IS OLD.updated_by
BEGIN
  UPDATE projects SET updated_at = strftime('%Y-%m-%d %H:%M:%f', 'now') WHERE id = NEW.id;
END;
