CREATE TRIGGER comments_escalation_event AFTER INSERT ON comments
WHEN NEW.kind = 'escalation'
BEGIN
  INSERT INTO events (kind, actor, target_kind, target_id, payload)
  VALUES ('comment.escalation', NEW.author, 'comment', NEW.id, json_object('target_kind', NEW.target_kind, 'target_id', NEW.target_id));
END;
CREATE TRIGGER idea_links_project BEFORE INSERT ON idea_links
WHEN (SELECT project_id FROM ideas WHERE id = NEW.idea_id) IS NOT (SELECT project_id FROM ideas WHERE id = NEW.target_id)
BEGIN
  SELECT RAISE(ABORT, 'idea_links: idea_id and target_id must be ideas of the same project');
END;
CREATE TRIGGER workers_kind BEFORE INSERT ON workers
WHEN NEW.kind NOT IN ('worker', 'watchdog', 'research') AND (SELECT json_type(config, '$.roles.' || json_quote(NEW.kind)) FROM projects WHERE id = NEW.project_id) IS NULL
BEGIN
  SELECT RAISE(ABORT, 'workers.kind must be a role of the project: worker, watchdog, research or a [roles.<name>] table of its piloop.toml');
END;
CREATE TRIGGER ideas_fts_insert AFTER INSERT ON ideas
BEGIN
  INSERT INTO ideas_fts (rowid, title, hypothesis, plan) VALUES (NEW.id, NEW.title, NEW.hypothesis, NEW.plan);
END;
CREATE TRIGGER ideas_fts_delete AFTER DELETE ON ideas
BEGIN
  INSERT INTO ideas_fts (ideas_fts, rowid, title, hypothesis, plan) VALUES ('delete', OLD.id, OLD.title, OLD.hypothesis, OLD.plan);
END;
CREATE TRIGGER ideas_fts_update AFTER UPDATE OF id, title, hypothesis, plan ON ideas
BEGIN
  INSERT INTO ideas_fts (ideas_fts, rowid, title, hypothesis, plan) VALUES ('delete', OLD.id, OLD.title, OLD.hypothesis, OLD.plan);
  INSERT INTO ideas_fts (rowid, title, hypothesis, plan) VALUES (NEW.id, NEW.title, NEW.hypothesis, NEW.plan);
END;
CREATE TRIGGER comments_fts_insert AFTER INSERT ON comments
BEGIN
  INSERT INTO comments_fts (rowid, body) VALUES (NEW.id, NEW.body);
END;
CREATE TRIGGER comments_fts_delete AFTER DELETE ON comments
BEGIN
  INSERT INTO comments_fts (comments_fts, rowid, body) VALUES ('delete', OLD.id, OLD.body);
END;
CREATE TRIGGER comments_fts_update AFTER UPDATE OF id, body ON comments
BEGIN
  INSERT INTO comments_fts (comments_fts, rowid, body) VALUES ('delete', OLD.id, OLD.body);
  INSERT INTO comments_fts (rowid, body) VALUES (NEW.id, NEW.body);
END;
